raw = open(P, 'rb').read(); L = raw.decode('utf-8').split('\n')
def table_end(head):
    idx = [i for i, s in enumerate(L) if s.startswith(head)]
    assert len(idx) == 1, (head, idx)
    i = idx[0] + 1
    while not L[i].startswith('|'): i += 1
    while i < len(L) and L[i].startswith('|'): i += 1
    return i  # insert position
# group by section, insert from the bottom of the file up so earlier positions stay valid
groups = {}
for h, row in R: groups.setdefault(h, []).append(row)
pos = sorted(((table_end(h), h) for h in groups), reverse=True)
for p, h in pos:
    rows = [r[:-1].rstrip() + T + ' |' for r in groups[h]]
    L[p:p] = rows
    print('%-50s +%d at line %d' % (h[:50], len(rows), p + 1))
# trap 144 at the end of the file
trap = '144. **tune_emu.Loader ends every dtbase run with "fault ... 3885957120" (a fetch at 0xe79f0000).** It still consumes the whole file and returns 0: INFERRED the harness\'s return, not a loader failure. (2026-10-22, gapL; `<archive>\\gapL\\RESULT.md`)' + T
while L and L[-1] == '': L.pop(); trail = True
L.append(trap); L.append('')
print('rows', len(R), '+ trap 144')
if APPLY:
    assert open(P, 'rb').read() == raw
    open(P, 'wb').write('\n'.join(L).encode('utf-8'))
    print('applied')
